import React, { useState, useEffect } from 'react';
import './GlobalEventNotification.css';

const GlobalEventNotification = ({ onEventClick }) => {
    const [activeEvent, setActiveEvent] = useState(null);

    useEffect(() => {
        const loadActiveEvent = async () => {
            try {
                const response = await api.get('/notifications');
                const eventNotif = response.data.find(n => n.type === 'event' && !n.read);
                if (eventNotif) {
                    setActiveEvent(eventNotif);
                }
            } catch (e) {
                console.error('Failed to load event notification', e);
            }
        };

        loadActiveEvent();

        // WebSocket будет обновлять автоматически через NotificationBell
        const handleNewNotification = (e) => {
            if (e.detail.type === 'event') {
                setActiveEvent(e.detail);
            }
        };
        window.addEventListener('newNotification', handleNewNotification);

        return () => window.removeEventListener('newNotification', handleNewNotification);
    }, []);

    if (!activeEvent) return null;

    return (
        <div className="global-event-notification" onClick={() => onEventClick && onEventClick()}>
            <div className="notification-bubble-glass">
                <div className="bubble-content-glass">
                    <div className="bubble-label-glass">БЛИЖАЙШЕЕ СОБЫТИЕ</div>
                    <div className="bubble-title-glass">{activeEvent.title}</div>
                    <div className="bubble-timer-glass">
                        {activeEvent.message}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default GlobalEventNotification;
